// src/wasm/index.ts
var WASM_BYTECODE = new Uint8Array([
  0,
  97,
  115,
  109,
  1,
  0,
  0,
  0,
  1,
  7,
  1,
  96,
  2,
  127,
  127,
  1,
  127,
  3,
  2,
  1,
  0,
  7,
  7,
  1,
  3,
  97,
  100,
  100,
  0,
  0,
  10,
  9,
  1,
  7,
  0,
  32,
  0,
  32,
  1,
  106,
  11
]);
var wasmInstance = null;
async function getWorkerWasm() {
  if (wasmInstance) {
    return wasmInstance.exports;
  }
  const { instance } = await WebAssembly.instantiate(WASM_BYTECODE);
  wasmInstance = instance;
  return instance.exports;
}

// src/processors/task.processor.ts
async function processTaskJob(jobData) {
  console.log(`[Worker Processor] Processing job ${jobData.id} (${jobData.name})...`);
  if (jobData.payload) {
    const wasm = await getWorkerWasm();
    const sum = wasm.add(jobData.payload.a, jobData.payload.b);
    console.log(`[Worker Processor] WASM computed: ${jobData.payload.a} + ${jobData.payload.b} = ${sum}`);
    return { success: true, result: sum };
  }
  return { success: true };
}

// src/queue.ts
function initializeQueueWorker(redisUrl) {
  if (!redisUrl) {
    console.log("[Worker Queue] No REDIS_URL provided. Running in standalone scheduled mode.");
    return null;
  }
  try {
    const connection = new import_ioredis.Redis(redisUrl, {
      maxRetriesPerRequest: null
    });
    const worker = new import_bullmq.Worker("pch-tasks", async (job) => {
      return processTaskJob(job.data);
    }, { connection });
    worker.on("completed", (job) => {
      console.log(`[Worker Queue] Job ${job.id} completed successfully.`);
    });
    worker.on("failed", (job, err) => {
      console.error(`[Worker Queue] Job ${job?.id} failed:`, err);
    });
    console.log('[Worker Queue] BullMQ worker initialized on queue "pch-tasks".');
    return worker;
  } catch (err) {
    console.error("[Worker Queue] Failed to initialize BullMQ worker:", err);
    return null;
  }
}

// src/index.ts
var isShuttingDown = false;
var heartbeatTimer = null;
async function startWorker() {
  console.log("----------------------------------------------------");
  console.log("[Worker] Starting PCH Background Worker on Render...");
  console.log(`[Worker] Runtime: Bun ${typeof Bun !== "undefined" ? Bun.version : "Node.js"}`);
  console.log(`[Worker] Environment: ${"development"}`);
  console.log("----------------------------------------------------");
  const redisUrl = process.env.REDIS_URL;
  const bullWorker = initializeQueueWorker(redisUrl);
  if (!bullWorker) {
    let tickCount = 0;
    heartbeatTimer = setInterval(async () => {
      if (isShuttingDown)
        return;
      tickCount += 1;
      console.log(`[Worker Heartbeat #${tickCount}] Worker alive at ${new Date().toISOString()}`);
      await processTaskJob({
        id: `interval-job-${tickCount}`,
        name: "periodic-wasm-compute",
        payload: { a: 10 * tickCount, b: 5 }
      });
    }, 30000);
  }
  const handleShutdown = async (signal) => {
    if (isShuttingDown)
      return;
    isShuttingDown = true;
    console.log(`
[Worker] Received ${signal}. Starting graceful shutdown...`);
    if (heartbeatTimer) {
      clearInterval(heartbeatTimer);
    }
    if (bullWorker) {
      console.log("[Worker] Closing BullMQ connections...");
      await bullWorker.close();
    }
    console.log("[Worker] Shutdown complete. Exiting.");
    process.exit(0);
  };
  process.on("SIGTERM", () => handleShutdown("SIGTERM"));
  process.on("SIGINT", () => handleShutdown("SIGINT"));
}
startWorker().catch((err) => {
  console.error("[Worker Fatal Error]:", err);
  process.exit(1);
});
